import math

def count_primes(n):
    """Counts the number of primes <= n (pi(n))"""
    count = 0
    is_prime = [True] * (n + 1)
    if n >= 0:
        is_prime[0] = False
    if n >= 1:
        is_prime[1] = False
    for p in range(2, n + 1):
        if is_prime[p]:
            count += 1
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
    return count

def calculate_k(n):
    """Approximates k = pi(n) - 2 based on W3/W1 derivation."""
    if n < 34:
        return None # Not relevant for the specific formula check
    pi_n = count_primes(n)
    # Using the derived simplification k = pi(n) - 2 for n >= 34
    k = pi_n - 2
    return k

